urdu11AddSection("urdu11-n09",{"id": "urdu11-s150-poem1", "title": "Jalwa-e-Sehar (Hafeez Jalandhari), part 1", "headingUrdu": "جلوۂ سحر (حفیظ جالندھری) (حصہ اوّل)", "headingPashto": "د سهار جلوه (حفیظ جالندهري) (لومړۍ برخه)", "sourceLanguage": "ur", "source": {"pdfPage": 150, "printedPage": "143"}, "auditStatus": "corrected; unresolved source", "flow": [{"type": "paragraphs", "ids": ["urdu11-s150-h1", "urdu11-s150-v2", "urdu11-s150-v3", "urdu11-s150-v4", "urdu11-s150-v5", "urdu11-s150-v6", "urdu11-s150-v7", "urdu11-s150-v8", "urdu11-s150-v9", "urdu11-s150-v10", "urdu11-s150-v11", "urdu11-s150-v12", "urdu11-s150-v13", "urdu11-s150-v14", "urdu11-s150-v15"]}], "equations": [], "sourceNote": "Printed page 143 (scan 150): title “جلوۂ سحر” (very faint in the scan), running head “حفیظ جالندھری”, and the first two stanzas of the poem, each printed as seven rows with a refrain repeated at the start and end. The scan is slightly out of focus. English and Pashto are our translations (need native review); watermark and ornamental borders excluded. The poem is printed in two columns of half-lines (right and left); each row is stored as one two-line item, right-hand half-line first.", "review": {"reviewedAtUtc": "2026-10-13T07:04:44.401935+00:00", "scope": "Scan 150 compared with source", "unresolved": "Translations need native review"}, "paras": [
urdu11Pair("جلوۂ سحر","Jalwa-e-Sehar (The Splendour of Dawn)","د سهار جلوه",{"id": "urdu11-s150-h1", "kind": "heading"}),
urdu11Pair("چلا ستارۂ سحر\nسنا کے صبح کی خبر","The star of dawn has set out,\nannouncing the news of morning.","د سهار ستوری روان شو\nد سهار خبر اورولو سره",{"id": "urdu11-s150-v2", "listType": "poem", "kind": "verse"}),
urdu11Pair("زمیں پہ نور چھا گیا\nفلک پہ رنگ آ گیا","Light spread over the earth;\ncolour came upon the sky.","پر ځمکه رڼا خپره شوه\nپر اسمان رنګ راغی",{"id": "urdu11-s150-v3", "listType": "poem", "kind": "verse"}),
urdu11Pair("تمام زادگانِ شب\nچمک چمک کے سو گئے","All the children of the night\ntwinkled and twinkled and went to sleep;","د شپې ټول زامن\nځلېدلو ځلېدلو سره ویده شول",{"id": "urdu11-s150-v4", "listType": "poem", "kind": "verse"}),
urdu11Pair("شرارِ آسمانِ شب\nدمک دمک کے سو گئے","the sparks of the night sky\nglowed and glowed and went to sleep.","د شپې اسمان څلانده\nځلېدلو ځلېدلو سره ویده شول",{"id": "urdu11-s150-v5", "listType": "poem", "kind": "verse"}),
urdu11Pair("ستارے زرد ہو چکے\nچراغ سرد ہو چکے","The stars have turned pale;\nthe lamps have turned cold.","ستوري ژیړ شوي دي\nڅراغونه سړه شوي دي",{"id": "urdu11-s150-v6", "listType": "poem", "kind": "verse"}),
urdu11Pair("وہ ٹمٹما کے رہ گئے\nیہ جھلملا کے رہ گئے","Those flickered and were left;\nthese glimmered and were left.","هغوی ټمټمېدو سره پاتې شول\nدغوی ځلېدو سره پاتې شول",{"id": "urdu11-s150-v7", "listType": "poem", "kind": "verse"}),
urdu11Pair("چلا ستارۂ سحر\nسنا کے صبح کی خبر","The star of dawn has set out,\nannouncing the news of morning.","د سهار ستوری روان شو\nد سهار خبر اورولو سره",{"id": "urdu11-s150-v8", "listType": "poem", "kind": "verse"}),
urdu11Pair("یکایک ایک نور کا\nغبارِ شرق سے اٹھا","Suddenly a cloud of light\nrose from the dust-cloud of the east;","ناڅاپه د یوې رڼا\nد ختیځ له غبار پورته شوه",{"id": "urdu11-s150-v9", "listType": "poem", "kind": "verse"}),
urdu11Pair("وہ رفتہ رفتہ بڑھ چلا\nاور آسماں پہ چھا گیا","it gradually advanced\nand spread over the sky.","هغه ورو ورو مخکې ولاړ\nاو پر اسمان خپره شوه",{"id": "urdu11-s150-v10", "listType": "poem", "kind": "verse"}),
urdu11Pair("حسینۂ نمود نے\nنقاب اٹھا دیا","The beauty of appearance\nlifted her veil;","د ښکاره کېدو ښکلې\nپرده پورته کړه",{"id": "urdu11-s150-v11", "listType": "poem", "kind": "verse"}),
urdu11Pair("فسوں گرِ شہود نے\nطلسمِ شب مٹا دیا","the enchanter of the witnessed world\nerased the spell of the night.","د مشاهدې افسونګر\nد شپې طلسم له منځه یووړ",{"id": "urdu11-s150-v12", "listType": "poem", "kind": "verse"}),
urdu11Pair("یکایک ایک تازگی\nیکایک ایک روشنی","Suddenly a freshness\nsuddenly a light","ناڅاپه یو تازګي\nناڅاپه یوه رڼا",{"id": "urdu11-s150-v13", "listType": "poem", "kind": "verse"}),
urdu11Pair("نگاہِ جاں میں آ گئی\nحیات میں سما گئی","came into the eye of the soul;\nmerged into life.","د ساه په سترګو کې راغله\nپه ژوند کې ننوته",{"id": "urdu11-s150-v14", "listType": "poem", "kind": "verse"}),
urdu11Pair("یکایک ایک نور کا\nغبارِ شرق سے اٹھا","Suddenly a cloud of light\nrose from the dust-cloud of the east.","ناڅاپه د یوې رڼا\nد ختیځ له غبار پورته شوه",{"id": "urdu11-s150-v15", "listType": "poem", "kind": "verse"})
]});
// END URDU SOURCE SCAN 150

